webpackJsonp([1],{"0wp8":function(n,r){},mlML:function(n,r,v){"use strict";Object.defineProperty(r,"__esModule",{value:!0});var _=v("/5sW"),b={render:function(){var n=this;n.$createElement;n._self._c;return n._m(0)},staticRenderFns:[function(){var n=this,r=n.$createElement,v=n._self._c||r;return v("div",{staticClass:"container"},[v("div",{staticClass:"content"},[n._v("\n            1.条款概述"),v("br"),n._v("\n● 娃娃路应用（以下简称“娃娃路”）由北京智同世纪科技有限公司（以下简称“智同世纪”）开发，根据以下服务条款为您提供服务。智同世纪在此特别提醒您（用户）在注册成为用户之前，请认真阅读本《用户协议》（以下简称“本协议”）及其各项附件（包括但不限于《娃娃路隐私政策》、《娃娃路用户行为规范》及其他附件），确保您充分理解本协议中各条款。除非您接受本协议所有条款，否则您无权注册、登录或使用本协议所涉服务。"),v("br"),n._v("\n● 此外，当您使用娃娃路服务时，您和娃娃路应遵守因国家政策以及法律法规变化进行修改的与该服务相关的指引和规则。前述所有的指引和规则，均构成本使用协议的一部分。"),v("br"),n._v("\n2.条款的修改"),v("br"),n._v("\n● 由于国家政策或法律法规的变化，本协议条款可能进行更新，修改后的条款由智同世纪向您通知或在网站上公告，用户可在本网站查阅最新版协议条款。"),v("br"),n._v("\n3.注册"),v("br"),n._v("\n● 为了能使用本服务，您需要注册娃娃路帐号，应当使用手机号码绑定注册，请用户使用尚未与“娃娃路”帐号绑定的手机号码注册“娃娃路”帐号。根据法律法规的要求，智同世纪可以根据用户需求或产品需要对帐号注册和绑定的方式进行变更，您应在法律法规的要求下予以配合。"),v("br"),n._v("\n● 鉴于娃娃路帐号的注册方式，且为了保护您账号的安全，您同意智同世纪在注册时使用您提供的手机号码及设备识别码等信息用于注册。"),v("br"),n._v("\n● 在用户注册及使用本服务时，智同世纪需要搜集能识别用户身份的个人信息以便智同世纪可以在必要时联系用户，或为用户提供更好的使用体验。智同世纪搜集的信息包括但不限于用户的姓名、性别、年龄、出生日期、地址、手机号码；智同世纪同意对这些信息的使用将受限于个人隐私信息相关法律和娃娃路隐私政策的约束。"),v("br"),n._v("\n● 您需要确保手机号码、名称等资料的真实性，以及在娃娃路上发布的所有内容的有效性和合法性。若您提供任何违法、违反道德以及违反娃娃路用户行为规范的资料，或者娃娃路有理由怀疑你进行任何恶意操作，则娃娃路有权限制或封禁您的帐号功能，并拒绝您于现在和未来使用本服务之全部或任何部分。任何用户应对其在娃娃路上发布的任何登记资料的真实性、正确性、完整性、适用性及/或是否为最新资料承担全部责任。"),v("br"),n._v("\n● 根据有关法律法规，娃娃路在此郑重提请您注意，任何经由本服务而发布、上传的文字、照片、或其它资料（以下简称“内容”），无论系公开还是私下传送，均受到版权保护，未经版权人授权同意禁止破解、复制和传播。经核实后，娃娃路有权依法停止服务并采取相应行动，包括但不限于暂停违规用户使用本服务的全部或部分，保存有关记录，并向有关机关报告。"),v("br"),n._v("\n4.用户帐号、密码及安全"),v("br"),n._v("\n● 完成本服务的注册程序并成功注册之后，您可使用您的手机号码，登录到您在娃娃路的帐号（下称“帐号”）。"),v("br"),n._v("\n● 您应对所有使用您的密码及帐号的活动负完全的责任。您同意："),v("br"),n._v("\n○ 您的娃娃路帐号遭到未获授权的使用，或者发生其它任何安全问题时，您将立即通知娃娃路，娃娃路将在合理的范围内保障您的权益。"),v("br"),n._v("\n○ 每个用户都要对其帐号中的所有行为和事件尽到合理注意义务。如果您未保管好自己的帐号和密码而对您、娃娃路或第三方造成的损害，您将在您的过错范围内承担责任。"),v("br"),n._v("\n○ 如娃娃路发现您的账号存在异常登录且账号被盗取的可能性较大，您同意娃娃路有权对账号进行冻结。如需解冻，请您通过娃娃路官方客服提出申请。\n5.付费功能使用"),v("br"),n._v("\n● 娃娃路部分增值服务需要付费使用，用户如需购买付费增值服务，可在娃娃路应用内进行支付并当日开通，若通过第三方购买兑换码可通过娃娃路官方客服兑换开通，开通时会通过官方客服确认服务内容，通过第三方购买时的其它承诺与娃娃路平台无关。"),v("br"),n._v("\n● 用户在购买前可通过娃娃路所公布的页面对相关增值服务的内容进行了解，如有疑问可通过官方客服进行确认。"),v("br"),n._v("\n● 用户购买时应根据实际需求确认购买服务的种类、数量、期限等。对于娃娃路依照法律法规的要求对违规用户进行封禁等处理的，用户不得再要求修改或退款。"),v("br"),n._v("\n● 用户购买娃娃路付费功能，要求开具发票的，娃娃路负责开具。如产生运输费、快递费等由用户承担。"),v("br"),n._v("\n6.供成员用于非商业用途"),v("br"),n._v("\n● 对于娃娃路所提供的服务，您不得用于任何商业用途，但经娃娃路明确认可或批准的商业使用除外。禁止非法和/或未经授权使用娃娃路服务。对于任何非法或未经授权使用娃娃路服务的行为，我们将会采取适当的法律行动。"),v("br"),n._v("\n7.用户个人隐私信息保护"),v("br"),n._v("\n● 用户在注册帐号或使用本服务的过程中，可能需要填写或提交一些必要的信息，如法律法规、规章规范性文件（以下称“法律法规”）规定的需要填写的身份信息。如用户提交的信息不完整或不符合法律法规的规定，则用户可能无法使用本服务或在使用本服务的过程中受到限制。"),v("br"),n._v("\n● 个人隐私信息是指涉及用户个人身份或个人隐私的信息，智同世纪十分注重保护用户的个人隐私，并制定了《娃娃路隐私政策》，用户可以通过阅读本协议附件进行具体查看，用户确认并同意使用智同世纪提供的服务将被视为接受《娃娃路隐私政策》。"),v("br"),n._v("\n8.用户行为规范"),v("br"),n._v("\n● 用户同意将不会利用本服务进行任何违法或不正当的活动，遵守娃娃路与用户之间的《娃娃路用户行为规范》。"),v("br"),n._v("\n9.国际使用之特别警告"),v("br"),n._v("\n● 您已了解国际互联网的无国界性，同意遵守当地所有关于网上行为及内容之法律法规。您特别同意遵守有关从中国或您所在国家或地区输出信息之传输的所有适用法律法规。"),v("br"),n._v("\n10.赔偿"),v("br"),n._v("\n● 由于您通过本服务下载内容、您违反本使用协议、或您侵害他人任何权利因而衍生或导致任何第三人提出任何索赔或请求，包括合理的律师费，您同意赔偿娃娃路及其子公司、关联企业、高级职员、代理人、品牌共有人或其它合作伙伴及员工，并使其免受损害，并承担由此引发的全部法律责任。"),v("br"),n._v("\n11.数据储存"),v("br"),n._v("\n● 智同世纪根据国际法律法规的要求对与用户有关的数据进行存储，并在您提出符合法律法规的请求后进行相关数据的删除。"),v("br"),n._v("\n12.服务的变更、中断、终止"),v("br"),n._v("\n● 鉴于网络服务的特殊性以及不定时修改的法律法规，用户理解智同世纪可能会在服务提供的过程中因非娃娃路的原因变更、中断或终止部分或全部的服务（包括收费服务）。智同世纪变更、中断或终止的服务，智同世纪应当在变更、中断或终止之前在“娃娃路”官网发布通告，并应向受影响的用户提供等值的替代性的服务；如用户不愿意接受替代性的服务，智同世纪应当按照该用户实际使用服务的情况扣除相应费用之后将剩余的金额退还用户。 如发生下列任何一种情形，智同世纪有权变更、中断或终止向用户提供的免费服务或收费服务，而无需对用户或任何第三方承担任何责任：(1) 根据法律规定用户应提交真实信息，而用户提供的个人资料不真实、或与注册时信息不一致又未能提供合理证明；(2) 用户违反相关法律法规或本协议的约定；(3) 按照法律规定或有权机关的要求；(4) 出于安全的原因或其他必要的情形。"),v("br"),n._v("\n13.担保与保证"),v("br"),n._v("\n● 您明确了解并同意:"),v("br"),n._v("\n○因第三方的原因造成对您的损害，您应根据《侵权责任法》等法律法规向侵权方进行追偿，娃娃路在法律法规规定的范围内予以配合。"),v("br"),n._v("\n14.责任限制：不可抗力"),v("br"),n._v("\n● 因下列不可抗力的原因导致双方不能履行合同或在合同范围内进行修改的，双方免除全部因不可抗力导致的不能履行或修改合同的责任： 1、因台风、地震、洪水、雷电、恐怖袭击、火灾、疫情、战争等原因； 2、因病毒、木马、恶意程序攻击、网络拥堵、系统不稳定、系统或设备故障、通讯故障、电力故障、第三方服务瑕疵或政府行为、法律法规的变化。 3、因您操作不当或违反政府规定或双方约定的行为规范损害公共秩序或侵害娃娃路、第三方权益的。"),v("br"),n._v("\n15.娃娃路商标信息"),v("br"),n._v("\n● 娃娃路L○g○、娃娃路以及其它娃娃路注册商标、标志及产品、服务名称，均为娃娃路公司之商标（以下简称“娃娃路标记”）。未经娃娃路事先书面同意，您同意不将娃娃路标记以任何方式展示或使用或作其它处理，或表示您有权展示、使用或另行处理娃娃路标记。"),v("br"),n._v("\n16.一般条款"),v("br"),n._v("\n● 本使用协议构成您娃娃路与之全部协议，并规范您对于本服务之使用行为。在您使用相关服务、使用第三方提供的内容或软件时，亦应遵从所适用之附加条款及条件；"),v("br"),n._v("\n● 本使用协议及您与娃娃路之关系，均受到中华人民共和国法律管辖。您与娃娃路就本服务、本使用协议或其它有关事项发生的争议，应首先友好协商解决，协商不成时应提请北京仲裁委员会仲裁，仲裁裁决是终局性的，对双方均有约束力；"),v("br"),n._v("\n● 娃娃路未行使或执行本使用协议任何权利或规定，不构成对前述权利或权利之放弃；"),v("br"),n._v("\n● 倘本使用协议之任何规定因与中华人民共和国法律抵触而无效，您依然同意应依照法律，努力使该规定所反映之当事人意向具备效力，且本使用协议其它规定仍应具有完整的效力及效果；"),v("br"),n._v("\n● 本使用协议之标题仅供方便而设，不具任何法律或契约效果。"),v("br"),v("br"),n._v("\n\n\n\n\n\n北京智同世纪科技有限公司\n        ")])])}]};var e=v("VU/8")({name:"index",data:function(){return{htmlText:""}},created:function(){this.htmlText=""}},b,!1,function(n){v("0wp8")},null,null).exports;new _.a({components:{index:e},render:function(n){return n(e)}}).$mount("#app")}},["mlML"]);
